     * `Changed`: check now (`check_for_changes`, `refresh_mailbox`); `TimedOut`: the
     * interval is over, check now too; `Cancelled`: stop. Blocks: call it from a
     * background task.
     */
    func wait(seconds: UInt32)  -> WatchOutcome
    
}
