public enum BlockKind: Equatable, Hashable {
    
    case paragraph
    case heading(level: UInt8
    )
    case listItem(marker: String, depth: UInt8
    )
    case code
    case rule
    /**
     * A remote image: show it only when the user allows remote images.
     */
    case image(src: String, alt: String
    )





}

#if compiler(>=6)
extension BlockKind: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeBlockKind: FfiConverterRustBuffer {
    typealias SwiftType = BlockKind

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> BlockKind {
        let variant: Int32 = try readInt(&buf)
        switch variant {
        
        case 1: return .paragraph
        
        case 2: return .heading(level: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 3: return .listItem(marker: try FfiConverterString.read(from: &buf), depth: try FfiConverterUInt8.read(from: &buf)
        )
        
        case 4: return .code
        
        case 5: return .rule
        
        case 6: return .image(src: try FfiConverterString.read(from: &buf), alt: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: BlockKind, into buf: inout [UInt8]) {
        switch value {
        
        
        case .paragraph:
            writeInt(&buf, Int32(1))
        
        
        case let .heading(level):
            writeInt(&buf, Int32(2))
            FfiConverterUInt8.write(level, into: &buf)
            
        
        case let .listItem(marker,depth):
            writeInt(&buf, Int32(3))
            FfiConverterString.write(marker, into: &buf)
            FfiConverterUInt8.write(depth, into: &buf)
            
        
        case .code:
            writeInt(&buf, Int32(4))
        
        
        case .rule:
            writeInt(&buf, Int32(5))
        
        
        case let .image(src,alt):
            writeInt(&buf, Int32(6))
            FfiConverterString.write(src, into: &buf)
            FfiConverterString.write(alt, into: &buf)
            
        }
    }
}


