        case 1: return .done
        
        case 2: return .moveToInbox
        
        case 3: return .trash
        
        case 4: return .untrash
        
        case 5: return .star
        
        case 6: return .unstar
        
        case 7: return .markRead
        
        case 8: return .markUnread
        
        case 9: return .spam
        
        case 10: return .notSpam
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: ThreadAction, into buf: inout [UInt8]) {
        switch value {
        
        
        case .done:
            writeInt(&buf, Int32(1))
        
        
        case .moveToInbox:
            writeInt(&buf, Int32(2))
        
        
        case .trash:
            writeInt(&buf, Int32(3))
        
        
        case .untrash:
            writeInt(&buf, Int32(4))
        
        
        case .star:
            writeInt(&buf, Int32(5))
        
        
        case .unstar:
            writeInt(&buf, Int32(6))
        
        
        case .markRead:
            writeInt(&buf, Int32(7))
        
        
        case .markUnread:
            writeInt(&buf, Int32(8))
        
        
        case .spam:
            writeInt(&buf, Int32(9))
        
        
        case .notSpam:
            writeInt(&buf, Int32(10))
        
        }
    }
}


