        )
        
        case 2: return .mail(to: try FfiConverterString.read(from: &buf), subject: try FfiConverterString.read(from: &buf), body: try FfiConverterString.read(from: &buf)
        )
        
        default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

